const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Great Fox Island area (Virginia, USA)
  const geometry = ee.Geometry.Polygon([[
    [-75.33, 37.89],
    [-75.31, 37.89],
    [-75.31, 37.91],
    [-75.33, 37.91],
    [-75.33, 37.89]
  ]]);

  // Function to calculate NDWI for water detection
  function addNDWI(image) {
    const ndwi = image.normalizedDifference(['B2', 'B4']).rename('NDWI');
    return image.addBands(ndwi);
  }

  // Function to calculate NDWI for Landsat 8
  function addNDWI_L8(image) {
    const ndwi = image.normalizedDifference(['B3', 'B5']).rename('NDWI');
    return image.addBands(ndwi);
  }

  // Get Landsat 5 collection for 1999
  let landsat1999 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(geometry)
    .filterDate('1999-01-01', '1999-12-31')
    .filter(ee.Filter.lt('CLOUD_COVER', 20))
    .map(addNDWI);

  // Get Landsat 8 collection for 2019
  let landsat2019 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(geometry)
    .filterDate('2019-01-01', '2019-12-31')
    .filter(ee.Filter.lt('CLOUD_COVER', 20))
    .map(addNDWI_L8);

  // Check if collections are empty
  const count1999 = landsat1999.size().getInfo();
  const count2019 = landsat2019.size().getInfo();

  console.log(`1999 Images: ${count1999}, 2019 Images: ${count2019}`);

  if (count1999 === 0 || count2019 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get median composites
  const composite1999 = landsat1999.median();
  const composite2019 = landsat2019.median();

  // Create land masks (NDWI < 0 = land, NDWI > 0 = water)
  const landMask1999 = composite1999.select('NDWI').lt(0);
  const landMask2019 = composite2019.select('NDWI').lt(0);

  // Count land pixels
  const landCount1999 = landMask1999.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 30,
    maxPixels: 1e9
  }).get('NDWI');

  const landCount2019 = landMask2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 30,
    maxPixels: 1e9
  }).get('NDWI');

  const count1 = landCount1999.getInfo();
  const count2 = landCount2019.getInfo();

  console.log(`1999 Land Pixels: ${count1}, 2019 Land Pixels: ${count2}`);

  // Check for no valid pixels
  if (count1 === 0 || count2 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failure
  if (count1 === null || count2 === null || isNaN(count1) || isNaN(count2)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Calculate area change
  const areaChange = ((count2 - count1) / count1 * 100);
  console.log(`Area Change: ${areaChange.toFixed(1)}%`);

  // Determine answer
  if (count2 < count1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
